import { writeFileSync, mkdirSync, chmodSync, existsSync } from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";
import { log } from "./logger.js";
import { t } from "./i18n.js";

const PROXY_DIR = join(homedir(), ".local", "bin");

function createProxyScript(
  name: string,
  targetExe: string,
  description: string,
): string {
  return `#!/bin/bash
# ${description}
# Auto-generated by wsl-android-emulation-launcher
exec "${targetExe}" "$@"
`;
}

export function installProxies(adbPath: string, emulatorPath: string): boolean {
  // ~/.local/bin ディレクトリを作成（存在しない場合）
  if (!existsSync(PROXY_DIR)) {
    try {
      mkdirSync(PROXY_DIR, { recursive: true });
      log.info(t.proxyDirCreated(PROXY_DIR));
    } catch (err) {
      log.error(t.proxyDirCreateFailed(PROXY_DIR, err));
      return false;
    }
  }

  const adbProxy = join(PROXY_DIR, "adb");
  const emulatorProxy = join(PROXY_DIR, "emulator");

  try {
    // adb プロキシを作成
    writeFileSync(adbProxy, createProxyScript("adb", adbPath, "ADB proxy for WSL → Windows"));
    chmodSync(adbProxy, 0o755);
    log.success(t.proxyInstalled("adb", adbProxy));

    // emulator プロキシを作成
    writeFileSync(
      emulatorProxy,
      createProxyScript("emulator", emulatorPath, "Android Emulator proxy for WSL → Windows"),
    );
    chmodSync(emulatorProxy, 0o755);
    log.success(t.proxyInstalled("emulator", emulatorProxy));

    return true;
  } catch (err) {
    log.error(t.proxyInstallFailed(err));
    return false;
  }
}

export function checkPathSetup(): void {
  const pathDirs = process.env.PATH?.split(":") || [];
  if (!pathDirs.includes(PROXY_DIR)) {
    log.warn(t.proxyNotInPath(PROXY_DIR));
    log.info(t.addToBashrc(PROXY_DIR));
    console.error("");
    console.error(`  export PATH="${PROXY_DIR}:$PATH"`);
    console.error("");
  }
}
